#include "Press78Engine.h"
#include "FactoryVoices.h"
#include "RecordedChorusProfile.h"
#include <array>
#include <cstdio>
#include <memory>
int main(int argc,char**argv){
 if(argc!=2)return 2;auto*f=std::fopen(argv[1],"wb");if(!f)return 3;
 for(double sr:{8000.,44100.,192000.})for(int voice:{65,93,97}){
  auto e=std::make_unique<press78::Press78Engine>();e->prepare(sr);
  press78::Controls c;c.chorusMode=1;c.chorusMix=1;c.chorusRateHz=press78::RecordedChorusProfile::rateHz;c.chorusDepthMs=press78::RecordedChorusProfile::depthMs;c.clockDriftPpm=20;c.drive=.12;
  e->setControls(c);e->setPatch(press78::decodeVoice(press78::kFactoryVoices[voice].bytes));e->noteOn(60,100);
  std::array<float,64>l{},r{};
  for(int block=0;block<192;++block){if(block==128)e->noteOff(60);e->process(l.data(),r.data(),l.size());std::fwrite(l.data(),sizeof(float),l.size(),f);std::fwrite(r.data(),sizeof(float),r.size(),f);}
 }
 return std::fclose(f);
}
